{
  "claims": [
    {
      "anchor": "By default the kubelet sends HTTP/2 requests for HTTP probes",
      "claim_text": "By default the kubelet sends HTTP/2 requests for HTTP probes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says default is HTTP/1.1, not HTTP/2."
    },
    {
      "anchor": "using HTTP/1.1 instead requires the H2CContainerProbe feature gate",
      "claim_text": "Using HTTP/1.1 instead requires the H2CContainerProbe feature gate.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "refutes"},
        {"sid": "P0.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Gate is required for HTTP2, not HTTP/1.1."
    },
    {
      "anchor": "A TCP probe considers the container healthy if it can open a socket on the given port",
      "claim_text": "A TCP probe considers the container healthy if it can open a socket on the given port.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"},
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Socket connection success means healthy."
    },
    {
      "anchor": "If the readiness probe fails, the kubelet restarts the container",
      "claim_text": "If the readiness probe fails, the kubelet restarts the container.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S4", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Failure marks pod unready, not restart."
    },
    {
      "anchor": "gRPC probes connect over TLS by default",
      "claim_text": "gRPC probes connect over TLS by default.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Default is plaintext, not TLS."
    },
    {
      "anchor": "in TLS mode the kubelet verifies the server certificate",
      "claim_text": "In TLS mode the kubelet verifies the server certificate.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S0", "rel": "refutes"},
        {"sid": "P5.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says certificate verification is not supported."
    },
    {
      "anchor": "The timeoutSeconds setting defaults to 1 second",
      "claim_text": "The timeoutSeconds setting defaults to 1 second.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S6", "rel": "entails", "sub": "timeoutSeconds setting (which defaults to 1s)"}
      ],
      "check": null,
      "reasoning": "Passage states default is 1s."
    },
    {
      "anchor": "If a startup probe never succeeds, the container keeps running but is never marked ready",
      "claim_text": "If a startup probe never succeeds, the container keeps running but is never marked ready.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says container is killed after 300s."
    },
    {
      "anchor": "Readiness probes only start after the liveness probe has succeeded",
      "claim_text": "Readiness probes only start after the liveness probe has succeeded.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P8.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Probes do not depend on each other."
    }
  ]
}
